def android_jar():
    """The newest platform android.jar of an installed SDK, or None."""
    bases = [os.environ.get("ANDROID_HOME"), os.environ.get("ANDROID_SDK_ROOT")]
    local = os.environ.get("LOCALAPPDATA")
    if local:
        bases.append(os.path.join(local, "Android", "Sdk"))
    for base in bases:
        if not base:
            continue
        plat = os.path.join(base, "platforms")
        if not os.path.isdir(plat):
            continue
        found = sorted((d for d in os.listdir(plat)
                        if os.path.isfile(os.path.join(plat, d, "android.jar"))),
                       key=lambda d: [int(x) for x in re.findall(r"\d+", d)] or [0])
        if found:
            return os.path.join(plat, found[-1], "android.jar")
    return None


def lua_runner():
    """argv prefix that runs a Lua file with arg[1..n], or None."""
    exe = shutil.which("texlua") or shutil.which("lua5.1") or shutil.which("luajit")
    if exe:
        return [exe]
    runner = os.path.join(ROOT, "tools", "run_lua_check.py")
    dll = r"C:\Program Files\LOVE\lua51.dll"
    if os.path.isfile(runner) and os.path.isfile(dll):
        return [sys.executable, runner]
    return None


CROSS_END = r"""package g2check;
import org.love2d.android.SecondDisplayHost;
import java.io.*;
import java.nio.file.*;

/** Feeds the Java end frames the Lua end wrote, and checks the touch mapping
 *  against the bounds the Lua end enforces. */
public class CrossEnd {
  static int fails = 0, checks = 0;
  static void ok(boolean c, String fmt, Object... a) {
    checks++;
    if (!c) { fails++; System.out.println("FAIL: " + String.format(fmt, a)); }
  }

  /** decodeHeader, but a throw counts as "did not refuse cleanly" rather than
   *  ending the run. The shipping caller wraps it in catch(Throwable), so a
   *  throw is survivable there -- but it must still be REPORTED here, or a
   *  missing length guard looks like a passing test that simply stopped. */
  static int[] decode(byte[] b) {
    try { return SecondDisplayHost.decodeHeader(b); }
    catch (Throwable t) { System.out.println("FAIL: decodeHeader threw " + t); fails++; return null; }
  }

  public static void main(String[] args) throws Exception {
    // ---- the frame the Lua transport produced ----
    byte[] frame = Files.readAllBytes(Paths.get(args[0]));
    int W = Integer.parseInt(args[1]), H = Integer.parseInt(args[2]);
    int expectSeq = Integer.parseInt(args[3]);

    byte[] head = new byte[SecondDisplayHost.HEADER_BYTES];
    System.arraycopy(frame, 0, head, 0, head.length);
    int[] hdr = decode(head);
    ok(hdr != null, "the Java end could not decode a header the Lua end wrote");
    if (hdr != null) {
      ok(hdr[0] == SecondDisplayHost.PROTOCOL, "version read as %d", hdr[0]);
      ok(hdr[1] == W, "width read as %d, Lua wrote %d", hdr[1], W);
      ok(hdr[2] == H, "height read as %d, Lua wrote %d", hdr[2], H);
      ok(hdr[3] == expectSeq, "sequence read as %d after %d push(es)", hdr[3], expectSeq);
      long want = (long) SecondDisplayHost.HEADER_BYTES + (long) W * H * 4L;
      ok(frame.length == want, "the file is %d bytes; this end expects %d",
         frame.length, want);
    }
    // a header from anything else must be refused, not drawn at a wrong size
    byte[] junk = new byte[12];
    ok(decode(junk) == null, "twelve zero bytes decoded as a frame");
    byte[] shortHead = new byte[11];
    System.arraycopy(head, 0, shortHead, 0, 11);
    ok(decode(shortHead) == null, "an 11-byte header decoded");
    byte[] badVer = head.clone(); badVer[4] = (byte) 99;
    ok(decode(badVer) == null, "protocol 99 decoded");
    byte[] badMagic = head.clone(); badMagic[2] = (byte) 'X';
    ok(decode(badMagic) == null, "bad magic decoded");

    // ---- the touch mapping, against the bounds Lua enforces ----
    // A 1280x720 panel showing a 256x192 screen letterboxes to 960x720 at x=160.
    int dl = 160, dt = 0, dw = 960, dh = 720;
    int[] c = SecondDisplayHost.mapPoint(dl + dw / 2f, dt + dh / 2f, dl, dt, dw, dh, W, H);
    ok(c != null && c[0] == W / 2 && c[1] == H / 2,
       "the panel's centre mapped to %s", c == null ? "nothing" : (c[0] + "," + c[1]));
    int[] tl = SecondDisplayHost.mapPoint(dl, dt, dl, dt, dw, dh, W, H);
    ok(tl != null && tl[0] == 0 && tl[1] == 0, "the top-left corner did not map to 0,0");
    int[] br = SecondDisplayHost.mapPoint(dl + dw - 1, dt + dh - 1, dl, dt, dw, dh, W, H);
    ok(br != null && br[0] == W - 1 && br[1] == H - 1,
       "the bottom-right mapped to %s, not %d,%d",
       br == null ? "nothing" : (br[0] + "," + br[1]), W - 1, H - 1);
    // THE LETTERBOX IS NOT A BUTTON. A clamped tap here is a press the player
    // never made, which is worse than a lost one.
    ok(SecondDisplayHost.mapPoint(10, 300, dl, dt, dw, dh, W, H) == null,
       "a tap in the left letterbox was mapped onto the screen");
    ok(SecondDisplayHost.mapPoint(1270, 300, dl, dt, dw, dh, W, H) == null,
       "a tap in the right letterbox was mapped onto the screen");
    // and every mapped point must satisfy the Lua guard: 0 <= x < 256, 0 <= y < 192
    java.util.Random r = new java.util.Random(7);
    int outside = 0;
    for (int i = 0; i < 20000; i++) {
      float px = r.nextFloat() * 1280f, py = r.nextFloat() * 720f;
      int[] p = SecondDisplayHost.mapPoint(px, py, dl, dt, dw, dh, W, H);
      if (p != null && (p[0] < 0 || p[0] >= W || p[1] < 0 || p[1] >= H)) outside++;
    }
    ok(outside == 0, "%d mapped point(s) fall outside the range Lua accepts", outside);

    // ---- casting: the kind, the mode, and both files ----
    ok(SecondDisplayHost.KIND_BUILTIN.equals(SecondDisplayHost.kindFromType(1)),
       "TYPE_INTERNAL is not built-in");
    for (int t = 2; t <= 5; t++)
      ok(SecondDisplayHost.KIND_EXTERNAL.equals(SecondDisplayHost.kindFromType(t)),
         "display type %d is not external", t);
    ok(SecondDisplayHost.kindFromType(0) == null && SecondDisplayHost.kindFromType(99) == null,
       "an unknown display type was given a kind");
    // DisplayInfo.toString as Android prints it for a Miracast sink, an HDMI
    // port, a Cast mirror, and a second built-in panel
    String wifi = "Display id 2: DisplayInfo{\"Living Room TV\", displayId 2, flags FLAG_PRESENTATION, real 1920 x 1080, rotation 0, type WIFI, address 7c:1c:4e:00:00:00, state ON, FLAG_PRESENTATION}";
    String hdmi = "Display id 1: DisplayInfo{\"HDMI Screen\", displayId 1, type EXTERNAL, address 0, state ON, FLAG_SECURE, FLAG_PRESENTATION}";
    String virt = "Display id 9: DisplayInfo{\"Cast screen\", displayId 9, type VIRTUAL, state ON, owner com.google.android.gms, FLAG_PRESENTATION}";
    String panel = "Display id 4: DisplayInfo{\"Built-in Screen\", displayId 4, type INTERNAL, address {port=1, model=0x0}, state ON, FLAG_PRESENTATION}";
    ok(SecondDisplayHost.KIND_EXTERNAL.equals(SecondDisplayHost.kindFromDescription(wifi)), "a Miracast sink is not external");
    ok(SecondDisplayHost.KIND_EXTERNAL.equals(SecondDisplayHost.kindFromDescription(hdmi)), "HDMI is not external");
    ok(SecondDisplayHost.KIND_EXTERNAL.equals(SecondDisplayHost.kindFromDescription(virt)), "a Cast mirror is not external");
    ok(SecondDisplayHost.KIND_BUILTIN.equals(SecondDisplayHost.kindFromDescription(panel)), "a built-in panel is not built-in");
    ok(SecondDisplayHost.kindFromDescription("Display id 3") == null, "an untyped description got a kind");
    // never set: a panel keeps the bottom screen, a TV mirrors
    ok("bottom".equals(SecondDisplayHost.effectiveMode(null, "builtin")), "an unset built-in panel is not bottom");
    ok("mirror".equals(SecondDisplayHost.effectiveMode(null, "external")), "an unset cast display is not mirror");
    ok("top".equals(SecondDisplayHost.effectiveMode("top", "builtin")), "an explicit top was overridden");
    ok("bottom".equals(SecondDisplayHost.effectiveMode("bottom", "external")), "an explicit bottom was overridden");

    // mode.txt bodies the LUA end wrote, through the Java parser
    if (args.length > 4) {
      String[][] modes = { {"mirror", "mirror"}, {"bottom", "bottom"}, {"top", "top"}, {"auto", null} };
      for (String[] m : modes) {
        byte[] body = Files.readAllBytes(Paths.get(args[4] + ".mode." + m[0]));
        String got = SecondDisplayHost.parseMode(new String(body, "UTF-8"));
        ok(m[1] == null ? got == null : m[1].equals(got),
           "Lua's mode.txt for %s parsed on the Java end as %s", m[0], got);
      }
      // host.txt lines THIS end writes, for the Lua end to parse
      StringBuilder sb = new StringBuilder();
      String[][] lines = {
        {"2", "1080", "1240", "builtin", "bottom"}, {"1", "0", "0", "external", "mirror"},
        {"2", "1920", "1080", "external", "top"}, {"1", "0", "0", "none", "auto"},
      };
      for (String[] l : lines) {
        sb.append(l[3]).append(' ').append(l[4]).append('|')
          .append(SecondDisplayHost.hostLine(Integer.parseInt(l[0]), Integer.parseInt(l[1]),
                  Integer.parseInt(l[2]), l[3], l[4]));
      }
      sb.append("none auto|").append(SecondDisplayHost.hostLine(1, 0, 0, null, null));
      Files.write(Paths.get(args[4] + ".hostlines"), sb.toString().getBytes("UTF-8"));
    }

    System.out.printf("%n%d checks, %d failed%n", checks, fails);
    System.exit(fails == 0 ? 0 : 1);
  }
}
"""

GEN_FRAME = r"""-- Writes a frame using the REAL src/render/SecondScreen.lua, so the bytes the
-- Java end is handed are the bytes the shipping Lua produces.
package.path="__ROOT__/?.lua;"..package.path
local FS={}
love={timer={getTime=function() return 1 end},
 filesystem={getInfo=function(p) local b=FS[p]; if not b then return nil end
   return {size=#b,modtime=5,type="file"} end,
  read=function(p) return FS[p] end,
  write=function(p,b) FS[p]=b or "" return true end,
  createDirectory=function() return true end}}
local T=require("src.render.SecondScreen")
local W,H = tonumber(arg[1]) or 256, tonumber(arg[2]) or 192
local px = {}
for i=1,W*H do px[i]=string.char(i%256, (i*7)%256, (i*13)%256, 255) end
local body=table.concat(px)
local img={body=body}; function img:getString() return self.body end
-- push() sends through the file transport only while a host is there, as on
-- a device; without this line it found none and wrote nothing
FS[T.HOST]="1 2 "..W.." "..H.." builtin bottom\n"
local pushes = tonumber(arg[3]) or 1
for _=1,pushes do assert(T.push(img,W,H)) end
local out=io.open(arg[4],"wb"); out:write(FS[T.FRAME]); out:close()
for _,m in ipairs({"mirror","bottom","top","auto"}) do
  assert(T.writeCastMode(m ~= "auto" and m or nil))
  local mf=io.open(arg[4]..".mode."..m,"wb"); mf:write(FS[T.MODE_FILE]); mf:close()
end
io.write(("lua wrote %d bytes for %dx%d after %d push(es)\n"):format(#FS[T.FRAME],W,H,pushes))
"""


LUA_PARSE = r"""-- Parses the host.txt lines the JAVA end wrote with the real Lua reader.
package.path="__ROOT__/?.lua;"..package.path
local FS={}
love={timer={getTime=function() return 1 end},
 filesystem={getInfo=function(p) local b=FS[p]; if not b then return nil end
   return {size=#b,modtime=5,type="file"} end,
  read=function(p) return FS[p] end,
  write=function(p,b) FS[p]=b or "" return true end,
  createDirectory=function() return true end}}
local T=require("src.render.SecondScreen")
local f=assert(io.open(arg[1],"rb")); local body=f:read("*a"); f:close()
local n=0
for expect, line in body:gmatch("([^|\n]+)|([^\n]*\n)") do
  n=n+1
  local ek, em = expect:match("^(%a+) (%a+)$")
  FS[T.HOST]=line
  local h=T.readHost()
  if not h or h.kind~=ek or h.mode~=em then
    io.write(("FAIL: the Java host line %q read on the Lua end as kind=%s mode=%s\n")
      :format(line, tostring(h and h.kind), tostring(h and h.mode)))
  end
end
io.write(("lua parsed %d java host line(s)\n"):format(n))
"""


def tier2():
    print("-- tier 2: a Lua-written frame, through the Java decoder")
    javac = shutil.which("javac")
    runner = lua_runner()
    if not javac:
        print("SKIPPED: no javac on PATH, so the Java end was not compiled.")
        return
    if not runner:
        print("SKIPPED: no texlua/lua on PATH and no LOVE lua51.dll, so no "
              "frame could be generated.")
        return
    jar = android_jar()
    print("   lua: %s" % " ".join(os.path.basename(x) for x in runner))
    print("   java end compiled against: %s" % (jar or "generated stubs"))
    tmp = tempfile.mkdtemp(prefix="g2sd-")
    try:
        src = os.path.join(tmp, "src")
        for rel, body in ({} if jar else STUBS).items():
            path = os.path.join(src, rel)
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "w") as fh:
                fh.write(body)
        for rel, body in (("g2check/CrossEnd.java", CROSS_END),):
            path = os.path.join(src, rel)
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "w") as fh:
                fh.write(body)
        dst = os.path.join(src, "org", "love2d", "android")
        os.makedirs(dst, exist_ok=True)
        shutil.copy(JAVA, os.path.join(dst, "SecondDisplayHost.java"))

        gen = os.path.join(tmp, "gen_frame.lua")
        with open(gen, "w") as fh:
            fh.write(GEN_FRAME.replace("__ROOT__", ROOT.replace("\\", "/")))
        frame = os.path.join(tmp, "frame.bin")
        W, H, PUSHES = 256, 192, 3
        r = subprocess.run(runner + [gen, str(W), str(H), str(PUSHES), frame],
                           capture_output=True, text=True)
        if not os.path.isfile(frame):
            ok(False, "the Lua end wrote no frame: %s"
               % (r.stderr.strip() or r.stdout.strip())[:300])
            return

        out = os.path.join(tmp, "out")
        os.makedirs(out, exist_ok=True)
        files = []
        for dp, _, fs in os.walk(src):
            files += [os.path.join(dp, f) for f in fs if f.endswith(".java")]
        cp = ["-cp", jar] if jar else []
        c = subprocess.run([javac, "-nowarn", "--release", "8", "-d", out]
                           + cp + files,
                           capture_output=True, text=True)
        if c.returncode != 0:
            ok(False, "the Java end does not compile: %s"
               % (c.stderr.strip().splitlines() or ["?"])[0])
            return
        java = shutil.which("java")
        runcp = out + (os.pathsep + jar if jar else "")
        r = subprocess.run([java, "-cp", runcp, "g2check.CrossEnd", frame,
                            str(W), str(H), str(PUSHES), frame],
                           capture_output=True, text=True)
        for line in r.stdout.splitlines():
            if line.startswith("FAIL"):
                CHECKS[0] += 1
                FAILS.append(line[6:])
                print(line)
            elif line.strip().endswith("failed"):
                m = re.match(r"(\d+) checks", line.strip())
                if m:
                    CHECKS[0] += int(m.group(1)) - len(
                        [l for l in r.stdout.splitlines() if l.startswith("FAIL")])
        if r.returncode != 0 and not any(l.startswith("FAIL")
                                         for l in r.stdout.splitlines()):
            ok(False, "the cross-end run failed: %s"
               % (r.stderr.strip().splitlines() or ["?"])[-1][:200])

        # ...and back: the host lines the Java end wrote, read by the Lua end
        lines = frame + ".hostlines"
        if os.path.isfile(lines):
            parse = os.path.join(tmp, "parse_host.lua")
            with open(parse, "w") as fh:
                fh.write(LUA_PARSE.replace("__ROOT__", ROOT.replace("\\", "/")))
            r = subprocess.run(runner + [parse, lines], capture_output=True,
                               text=True)
            parsed = re.search(r"lua parsed (\d+)", r.stdout)
            ok(parsed and int(parsed.group(1)) == 5,
               "the Lua end parsed %s of the Java end's 5 host lines: %s"
               % (parsed.group(1) if parsed else "none",
                  (r.stderr or r.stdout).strip()[:200]))
            for line in r.stdout.splitlines():
                ok(not line.startswith("FAIL"), line[6:])
        else:
            ok(False, "the Java end wrote no host lines")
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


# ---------------------------------------------------------------------------
# TIER 3 -- the iOS host (GRCastBridge.swift), by its source
# ---------------------------------------------------------------------------
def tier3():
    print("-- tier 3: the iOS host's source against the Lua end")
    for path in (SWIFT, GUARD, IOS_PATCH):
        if not os.path.isfile(path):
            ok(False, "%s is missing" % os.path.relpath(path, ROOT))
            return
    lua, swift = read(LUA), read(SWIFT)
    guard, patch = read(GUARD), read(IOS_PATCH)

    def lua_const(name):
        m = re.search(r"SecondScreen\.%s\s*=\s*(.+)" % name, lua)
        return m.group(1).strip() if m else None

    def lua_leaf(name):
        m = re.search(r'"([^"]+)"', lua_const(name) or "")
        return m.group(1).lstrip("/") if m else None

    def swift_const(name):
        m = re.search(r"static let %s(?:\s*:\s*\w+)?\s*=\s*(.+)" % name, swift)
        return m.group(1).strip().strip('"') if m else None

    ok(swift_const("protocolVersion") == (lua_const("PROTOCOL") or "?"),
       "protocol version: Lua says %s, the iOS host %s"
       % (lua_const("PROTOCOL"), swift_const("protocolVersion")))
    ok(swift_const("dirName") == (lua_const("DIR") or "").strip('"'),
       "the iOS host's directory is %s, Lua's %s"
       % (swift_const("dirName"), lua_const("DIR")))
    for lname, sname in (("HOST", "hostFile"), ("FRAME", "frameFile"),
                         ("MODE_FILE", "modeFile")):
        ok(swift_const(sname) and swift_const(sname) == lua_leaf(lname),
           "%s: Lua's leaf is %s, the iOS host's %s"
           % (lname, lua_leaf(lname), swift_const(sname)))

    def lua_words(name):
        m = re.search(r"SecondScreen\.%s\s*=\s*\{([^}]*)\}" % name, lua)
        return set(re.findall(r'"(\w+)"', m.group(1))) if m else set()

    modes = {swift_const(n) for n in ("modeMirror", "modeBottom", "modeTop")}
    kinds = {swift_const(n) for n in ("kindNone", "kindExternal")}
    ok(modes == lua_words("CAST_MODES"),
       "the iOS host's modes %s, Lua's %s" % (sorted(modes), sorted(lua_words("CAST_MODES"))))
    ok(kinds <= lua_words("CAST_KINDS") and "builtin" not in kinds,
       "the iOS host's kinds %s are not Lua's minus builtin" % sorted(kinds))
    ok(swift_const("modeAuto") == "auto", "the iOS host's never-set word is %s"
       % swift_const("modeAuto"))
    ok("requested ?? modeMirror" in swift,
       "the iOS host's never-set mode on a TV is not mirror")
    ok("touch" not in re.sub(r"//[^\n]*", "", swift),
       "the iOS host's code touches touch.txt; a TV routes no taps")

    # the host.txt template, rendered, through the REAL Lua reader
    m = re.search(r"static func hostLine\(.*?\{\s*return \"(.*?)\"\s*\}", swift, re.S)
    ok(m is not None, "GRCastBridge.hostLine's template was not found")
    runner = lua_runner()
    if m and runner:
        template = m.group(1)

        def render(displays, w, h, kind, mode):
            s = template
            for k, v in (("protocolVersion", swift_const("protocolVersion")),
                         ("displays", displays), ("width", w), ("height", h),
                         ("kind", kind), ("mode", mode)):
                s = s.replace("\\(%s)" % k, str(v))
            return s.replace("\\n", "\n")

        cases = [(1, 0, 0, "none", "auto"), (1, 0, 0, "none", "top"),
                 (1, 0, 0, "external", "mirror"), (2, 640, 360, "external", "bottom"),
                 (2, 640, 360, "external", "top")]
        tmp = tempfile.mkdtemp(prefix="g2sd-ios-")
        try:
            lines = os.path.join(tmp, "hostlines")
            with open(lines, "w", newline="") as fh:
                for c in cases:
                    line = render(*c)
                    ok("\\(" not in line and line.endswith("\n"),
                       "the Swift template rendered as %r" % line)
                    fh.write("%s %s|%s" % (c[3], c[4], line))
            parse = os.path.join(tmp, "parse_host.lua")
            with open(parse, "w") as fh:
                fh.write(LUA_PARSE.replace("__ROOT__", ROOT.replace("\\", "/")))
            r = subprocess.run(runner + [parse, lines], capture_output=True, text=True)
            parsed = re.search(r"lua parsed (\d+)", r.stdout)
            ok(parsed and int(parsed.group(1)) == len(cases),
               "the Lua end parsed %s of the iOS host's %d lines: %s"
               % (parsed.group(1) if parsed else "none", len(cases),
                  (r.stderr or r.stdout).strip()[:200]))
            for line in r.stdout.splitlines():
                ok(not line.startswith("FAIL"), line[6:].replace("Java", "iOS"))

            # a frame the real Lua wrote, decoded with the Swift's offsets
            magic = re.findall(r"bytes\[(\d)\] == 0x([0-9A-Fa-f]{2})", swift)
            mword = "".join(chr(int(b, 16)) for _, b in sorted(magic))
            ok(mword == (lua_const("MAGIC") or "").strip('"'),
               "the iOS host checks the magic %r, Lua writes %s"
               % (mword, lua_const("MAGIC")))
            hb = swift_const("headerBytes")
            ok(hb == "12", "the iOS host's header is %s bytes, not 12" % hb)
            off = {}
            for name, pat in (("version", r"guard u16\((\d+)\) == GRCastBridge\.protocolVersion"),
                              ("width", r"let w = u16\((\d+)\)"),
                              ("height", r"h = u16\((\d+)\)"),
                              ("seq", r"seq: u16\((\d+)\)")):
                mm = re.search(pat, swift)
                off[name] = int(mm.group(1)) if mm else None
                ok(mm is not None, "the iOS host's %s offset was not found" % name)
            gen = os.path.join(tmp, "gen_frame.lua")
            with open(gen, "w") as fh:
                fh.write(GEN_FRAME.replace("__ROOT__", ROOT.replace("\\", "/")))
            frame = os.path.join(tmp, "frame.bin")
            W, H, PUSHES = 64, 48, 3
            subprocess.run(runner + [gen, str(W), str(H), str(PUSHES), frame],
                           capture_output=True, text=True)
            if os.path.isfile(frame) and None not in off.values():
                with open(frame, "rb") as fh:
                    b = fh.read()

                def u16(at):
                    return b[at] | (b[at + 1] << 8)
                ok(u16(off["version"]) == int(swift_const("protocolVersion") or -1),
                   "the iOS host reads version %d" % u16(off["version"]))
                ok(u16(off["width"]) == W and u16(off["height"]) == H,
                   "the iOS host reads %dx%d, Lua wrote %dx%d"
                   % (u16(off["width"]), u16(off["height"]), W, H))
                ok(u16(off["seq"]) == PUSHES,
                   "the iOS host reads sequence %d after %d pushes"
                   % (u16(off["seq"]), PUSHES))
                ok(len(b) == 12 + W * H * 4,
                   "a Lua frame is %d bytes; the iOS host wants %d"
                   % (len(b), 12 + W * H * 4))
            else:
                ok(False, "no Lua frame to decode with the iOS host's offsets")
        finally:
            shutil.rmtree(tmp, ignore_errors=True)
    elif not runner:
        print("SKIPPED: no Lua, so the iOS host lines were not parsed.")

    # the build: both files compiled, the Lua entry point registered
    for name in ("GRCastBridge.swift", "GRSceneGuard.m"):
        ok(patch.count('"%s"' % name) >= 2,
           "patch_love_src.py does not copy and compile %s" % name)
    ok('{ "castHostStart", w_castHostStart }' in patch,
       "patch_love_src.py does not register love.system.castHostStart")
    ok('"GRCastBridge", "startWithCommand:saveDir:"' in patch
       and "@objc(startWithCommand:saveDir:)" in swift
       and "@objc(GRCastBridge)" in swift,
       "wrap_System's castHostStart does not reach GRCastBridge.start")
    ok("love.system.castHostStart" in lua and 'os == "iOS"' not in lua
       and 'name == "iOS"' in lua,
       "the Lua end does not start the iOS host itself")
    # the scene guard: SDL must leave AirPlay scenes to iOS
    for needle in ("SDLUIKitSceneDelegate", "scene:willConnectToSession:options:",
                   "UIWindowSceneSessionRoleExternalDisplayNonInteractive",
                   "UIWindowSceneSessionRoleExternalDisplay]",
                   "sceneDidBecomeActive:", "sceneWillResignActive:",
                   "sceneWillEnterForeground:", "sceneDidEnterBackground:",
                   "__attribute__((constructor))"):
        ok(needle in guard, "GRSceneGuard.m lacks %s" % needle)


tier1()
tier2()
tier3()
print("\n%d checks, %d failed" % (CHECKS[0], len(FAILS)))
sys.exit(1 if FAILS else 0)
